script:
test("partial hour rounds up", function () {
  var actual = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-10 10:01" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 121, roundedHours: 3, billableHours: 3, flags: [] });
});

test("spring-forward night counts real elapsed time and leaves exact hours unchanged", function () {
  var actual = code.billableObservationHours({ admission: "2026-03-07 22:00", discharge: "2026-03-08 22:00" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 1380, roundedHours: 23, billableHours: 23, flags: [] });
});

test("fall-back night counts real elapsed time", function () {
  var actual = code.billableObservationHours({ admission: "2026-10-31 22:00", discharge: "2026-11-01 22:00" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 1500, roundedHours: 25, billableHours: 25, flags: [] });
});

test("a stay well above 48 hours is billed as 48", function () {
  var actual = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-13 08:00" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 4320, roundedHours: 72, billableHours: 48, flags: [] });
});

test("exactly 48 hours across the year boundary stays 48", function () {
  var actual = code.billableObservationHours({ admission: "2025-12-31 08:00", discharge: "2026-01-02 08:00" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 2880, roundedHours: 48, billableHours: 48, flags: [] });
});

test("one hour under the cap is not capped", function () {
  var actual = code.billableObservationHours({ admission: "2025-12-31 08:00", discharge: "2026-01-02 07:00" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 2820, roundedHours: 47, billableHours: 47, flags: [] });
});

test("one hour over the cap is billed as 48", function () {
  var actual = code.billableObservationHours({ admission: "2025-12-31 08:00", discharge: "2026-01-02 09:00" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 2940, roundedHours: 49, billableHours: 48, flags: [] });
});

test("equal admission and discharge is zero hours and not invalid", function () {
  var actual = code.billableObservationHours({ admission: "2026-01-01 00:00", discharge: "2026-01-01 00:00" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 0, roundedHours: 0, billableHours: 0, flags: [] });
});

test("one real minute beside the spring gap rounds up to 1 hour", function () {
  var actual = code.billableObservationHours({ admission: "2026-03-08 01:59", discharge: "2026-03-08 03:00" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 1, roundedHours: 1, billableHours: 1, flags: [] });
});

test("leap day partial hour rounds up", function () {
  var actual = code.billableObservationHours({ admission: "2024-02-29 10:00", discharge: "2024-03-01 10:01" });
  assert.deepEqual(actual, { status: "ok", elapsedMinutes: 1441, roundedHours: 25, billableHours: 25, flags: [] });
});

test("discharge one minute earlier is invalid and the flag names discharge", function () {
  var actual = code.billableObservationHours({ admission: "2026-01-31 12:00", discharge: "2026-01-31 11:59" });
  assert.equal(actual.status, "invalid");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.equal(actual.flags.length, 1);
  assert.match(actual.flags[0], /discharge/);
});

test("ambiguous admission at 01:30 is flagged and the flag names admission", function () {
  var actual = code.billableObservationHours({ admission: "2026-11-01 01:30", discharge: "2026-11-01 12:00" });
  assert.equal(actual.status, "ambiguous");
  assert.equal(actual.elapsedMinutes, null);
  assert.equal(actual.roundedHours, null);
  assert.equal(actual.billableHours, null);
  assert.equal(actual.flags.length, 1);
  assert.match(actual.flags[0], /admission/);
});

test("ambiguous discharge at 01:00 inclusive is flagged and the flag names discharge", function () {
  var actual = code.billableObservationHours({ admission: "2026-11-01 00:00", discharge: "2026-11-01 01:00" });
  assert.equal(actual.status, "ambiguous");
