test("nonexistent discharge at 02:30 is flagged and the flag names discharge", function () {
  var actual = code.billableObservationHours({ admission: "2026-03-08 00:30", discharge: "2026-03-08 02:30" });
  assert.equal(actual.status, "nonexistent");
